const requested = $input.first()?.json || {};
const maxMessages = requested.maxMessages ?? 500;
const pageSize = requested.pageSize ?? 100;
const requestDelayMs = requested.requestDelayMs ?? 200;

if (!Number.isInteger(maxMessages) || maxMessages < 1 || maxMessages > 10000) throw new Error('maxMessages must be an integer from 1 to 10000');
if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 500) throw new Error('pageSize must be an integer from 1 to 500');
if (!Number.isInteger(requestDelayMs) || requestDelayMs < 0 || requestDelayMs > 60000) throw new Error('requestDelayMs must be an integer from 0 to 60000');

const maxPages = Math.min(10000, Math.max(1, Math.ceil(maxMessages / pageSize) * 2));
return [{ json: {
  maxMessages,
  pageSize,
  requestDelayMs,
  maxPages,
  apiRequests: 0,
  retryCount: 0,
  partial: false,
  errors: [],
  pagination: {
    nextPageToken: null,
    pagesFetched: 0,
    messagesDiscovered: 0,
    messageIds: [],
    seenPageTokens: [],
    hasMorePages: true
  }
} }];

const items = $input.all();
if (items.length !== 1) throw new Error(`Expected one pagination-state item, got ${items.length}`);
return [{ json: { pageState: items[0].json } }];

const items = $input.all();
if (items.length !== 1) throw new Error(`Expected one Gmail page response, got ${items.length}`);
return [{ json: { pageResponse: items[0].json } }];

const items = $input.all();
if (items.length !== 1) throw new Error(`Expected one paired page item, got ${items.length}`);
const pair = items[0].json;
const state = pair.pageState;
const response = pair.pageResponse;
if (!state?.pagination || !response) throw new Error('Missing pagination state or Gmail response in paired page item');

const statusCode = response.statusCode;
const pagination = state.pagination;
const nextPagesFetched = pagination.pagesFetched + 1;
const apiRequests = state.apiRequests + 1;
const errors = [...state.errors];
let messageIds = [...pagination.messageIds];
let messagesDiscovered = pagination.messagesDiscovered;
let seenPageTokens = [...pagination.seenPageTokens];
let nextPageToken = null;
let hasMorePages = false;
let partial = state.partial;

if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) {
  errors.push(`Gmail list request failed (HTTP ${Number.isInteger(statusCode) ? statusCode : 'unknown'}).`);
  return [{ json: { ...state, apiRequests, partial: true, errors, pagination: { ...pagination, pagesFetched: nextPagesFetched, hasMorePages: false } } }];
}

const body = response.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Gmail list response did not contain a JSON object.');
  return [{ json: { ...state, apiRequests, partial: true, errors, pagination: { ...pagination, pagesFetched: nextPagesFetched, hasMorePages: false } } }];
}
const messages = body.messages ?? [];
if (!Array.isArray(messages)) throw new Error('Unexpected Gmail messages list format');
if (messages.length > state.pageSize) throw new Error('Gmail returned more messages than requested pageSize');

const knownIds = new Set(messageIds);
let addedThisPage = 0;
for (const message of messages) {
  if (typeof message?.id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(message.id)) throw new Error('Invalid Gmail message ID format');
  if (!knownIds.has(message.id) && messageIds.length < state.maxMessages) {
    knownIds.add(message.id);
    messageIds.push(message.id);
    addedThisPage++;
  }
}
messagesDiscovered += messages.length;
nextPageToken = typeof body.nextPageToken === 'string' && body.nextPageToken.length > 0 ? body.nextPageToken : null;

if (nextPageToken && seenPageTokens.includes(nextPageToken)) {
  errors.push('Gmail returned a repeated page token; pagination stopped.');
  partial = true;
  nextPageToken = null;
} else if (nextPageToken) {
  seenPageTokens.push(nextPageToken);
}

if (nextPageToken && addedThisPage === 0) {
  errors.push('Gmail pagination made no progress; pagination stopped.');
  partial = true;
  nextPageToken = null;
}

const reachedLimit = messageIds.length >= state.maxMessages;
if (reachedLimit && nextPageToken) partial = true;
hasMorePages = Boolean(nextPageToken) && !reachedLimit;
if (hasMorePages && nextPagesFetched >= state.maxPages) {
  errors.push('Maximum page-request limit reached; pagination stopped.');
  partial = true;
  hasMorePages = false;
}

return [{ json: {
  ...state,
  apiRequests,
  partial,
  errors,
  pagination: {
    nextPageToken: hasMorePages ? nextPageToken : null,
    pagesFetched: nextPagesFetched,
    messagesDiscovered,
    messageIds,
    seenPageTokens,
    hasMorePages
  }
} }];

const items = $input.all();
if (items.length !== 1) throw new Error(`Expected one state item before delay, got ${items.length}`);
const state = items[0].json;
if (!Number.isInteger(state.requestDelayMs) || state.requestDelayMs < 0) throw new Error('Invalid requestDelayMs');
await new Promise((resolve) => setTimeout(resolve, state.requestDelayMs));
return [{ json: state }];

const items = $input.all();
if (items.length !== 1) throw new Error(`Expected one completed pagination item, got ${items.length}`);
const state = items[0].json;
const ids = state.pagination.messageIds;
if (!Array.isArray(ids) || ids.length > state.maxMessages) throw new Error('Invalid accumulated message ID list');
if (ids.length === 0) return [{ json: { skipMetadata: true, requestContext: { state }, metadataResponse: null } }];
return ids.map((id) => ({ json: { skipMetadata: false, requestContext: { id, state } } }));

const items = $input.all();
if (items.length === 0) throw new Error('No metadata result items received');
const state = items[0].json.requestContext?.state;
if (!state) throw new Error('Missing pagination state in metadata context');

const groups = new Map();
const processedIds = new Set();
const errors = [...state.errors];
let unknownSenderCount = 0;
let messagesAnalyzed = 0;

for (const item of items) {
  const context = item.json.requestContext;
  const response = item.json.metadataResponse;
  if (!context?.state || context.state.pagination.pagesFetched !== state.pagination.pagesFetched) throw new Error('Metadata context does not match the final pagination state');
  if (!context.id) continue;
  const status = response?.statusCode;
  if (!Number.isInteger(status) || status < 200 || status >= 300) {
    errors.push(`Gmail metadata request failed (HTTP ${Number.isInteger(status) ? status : 'unknown'}).`);
    continue;
  }
  const message = response.body;
  if (!message || message.id !== context.id || processedIds.has(message.id)) {
    errors.push('Gmail metadata response was missing, mismatched, or duplicated.');
    continue;
  }
  processedIds.add(message.id);
  messagesAnalyzed++;
  const headers = message.payload?.headers;
  if (!Array.isArray(headers) || headers.some((header) => !header || typeof header.name !== 'string' || typeof header.value !== 'string')) {
    unknownSenderCount++;
    continue;
  }
  const values = (name) => headers.filter((header) => header.name.toLowerCase() === name).map((header) => header.value);
  const from = values('from');
  const raw = from.length === 1 ? from[0].trim() : '';
  const angle = raw.match(/^\s*[^<>]*<\s*([^<>\s]+)\s*>\s*$/);
  const addressCandidate = raw.includes('<') || raw.includes('>') ? (angle?.[1] ?? '') : raw;
  const address = addressCandidate.trim().toLowerCase();
  const parts = address.split('@');
  const local = parts[0];
  const domain = parts[1];
  const validLocal = local.length <= 64 && local.split('.').every((part) => /^[a-z0-9!#$%&'*+/?^_`{|}~-]+$/i.test(part));
  const validDomain = domain && domain.length <= 253 && domain.split('.').every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label));
  if (parts.length !== 2 || !validLocal || !validDomain) {
    unknownSenderCount++;
    continue;
  }
  if (!groups.has(address)) groups.set(address, { sender: address, count: 0, signals: { listUnsubscribe: 0, bulkOrListPrecedence: 0, noReplyAddress: 0 } });
  const group = groups.get(address);
  group.count++;
  if (values('list-unsubscribe').some((value) => value.trim() !== '')) group.signals.listUnsubscribe++;
  if (values('precedence').some((value) => /^(bulk|list|junk)$/i.test(value.trim()))) group.signals.bulkOrListPrecedence++;
  if (/^(no[-_.]?reply|do[-_.]?not[-_.]?reply|notifications?)$/.test(local)) group.signals.noReplyAddress++;
}

const senders = [...groups.values()].map((group) => ({
  ...group,
  category: Object.values(group.signals).some((count) => count > 0) ? 'potential_newsletter_or_automated' : 'no_signal',
  safeToDelete: false
})).sort((a, b) => b.count - a.count || a.sender.localeCompare(b.sender));
const apiRequests = state.apiRequests + state.pagination.messageIds.length;
const partial = state.partial || errors.length > 0 || messagesAnalyzed < state.pagination.messageIds.length;
return [{ json: {
  maxMessages: state.maxMessages,
  pageSize: state.pageSize,
  messagesDiscovered: state.pagination.messagesDiscovered,
  messagesAnalyzed,
  unknownSenderCount,
  uniqueSenderCount: groups.size,
  pagesFetched: state.pagination.pagesFetched,
  apiRequests,
  retryCount: state.retryCount,
  partial,
  errors,
  senders
} }];
